import sys
from collections import deque

def min_distance(a, b):
    d1 = abs(ord(a) - ord(b))
    d2 = 26 - d1
    return min(d1, d2)

def max_occurrences(N, M, K, S, T):
    dp = [[-1] * (K + 1) for _ in range(M + 1)]
    dp[0][0] = 0

    for i in range(1, M + 1):
        for k in range(K + 1):
            if dp[i - 1][k] != -1:
                dp[i][k] = dp[i - 1][k]
            for j in range(max(0, i - N + 1), i):
                cost = sum(min_distance(S[l], T[j + l - (i - N + 1)]) for l in range(i - (j - (i - N + 1))))
                if k + cost <= K:
                    new_count = dp[j][k + cost] + (S == T[j:j + N])
                    dp[i][k] = max(dp[i][k], new_count)
    return max(max(row) for row in dp)

input = sys.stdin.read().strip().split()
N, M, K = map(int, input[:3])
S, T = input[3], input[4]
print(max_occurrences(N, M, K, S, T))
